  return <div className="animate-rise"><PageHeading eyebrow="Área de administração" title="Criar Revendedor" description="Crie uma conta de revendedor com acesso separado do administrador." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="surface rounded-2xl p-6"><div className="mb-5 flex items-center gap-3"><UserPlus className="text-[#50d7e5]" /><div><h2 className="font-bold text-white">Novo revendedor</h2><p className="text-xs text-[#777780]">Use um Gmail e defina o acesso inicial.</p></div></div><input className="input-dark mb-3" type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="revendedor@gmail.com" /><input className="input-dark mb-3" value={name} onChange={event => setName(event.target.value)} placeholder="Nome completo" /><input className="input-dark mb-3" value={username} onChange={event => setUsername(event.target.value)} placeholder="Nome de usuário" /><input className="input-dark" type="password" value={password} onChange={event => setPassword(event.target.value)} placeholder="Senha inicial" /><button className="btn-red mt-4 w-full" disabled={create.isPending || !email || !name || !username || !password} onClick={() => create.mutate({ email, name, username, password })}><UserPlus size={16} /> Criar revendedor</button></div><div className="surface overflow-hidden rounded-2xl"><div className="border-b border-white/[.06] p-5"><p className="font-bold text-white">Contas cadastradas</p></div><div className="divide-y divide-white/[.06]">{users.data?.map(item => <div key={item.id} className="flex items-center justify-between gap-3 p-4"><div><p className="font-semibold text-white">{item.name || item.email}</p><p className="text-xs text-[#777780]">{item.email || "Sem Gmail"}</p></div><span className="rounded-full bg-[#50d7e5]/10 px-3 py-1 text-xs font-bold text-[#50d7e5]">{item.role === "reseller" ? "Revendedor" : item.role === "admin" ? "Administrador" : "Cliente"}</span></div>)}</div></div></div></div>;
