function AdminMods() {
  const query = trpc.admin.mods.useQuery(); const [name, setName] = useState(""); const [status, setStatus] = useState<"online" | "offline" | "maintenance">("online");
  const create = trpc.admin.createMod.useMutation({ onSuccess: () => { toast.success("Mod cadastrado."); setName(""); query.refetch(); }, onError: error => toast.error(error.message) }); const update = trpc.admin.updateModStatus.useMutation({ onSuccess: () => query.refetch(), onError: error => toast.error(error.message) }); const remove = trpc.admin.deleteMod.useMutation({ onSuccess: () => query.refetch(), onError: error => toast.error(error.message) });
  return <div className="animate-rise"><PageHeading eyebrow="Área de administração" title="Status dos Mods" description="Controle as bolinhas de status exibidas para os usuários." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="surface rounded-2xl p-6"><div className="mb-5 flex items-center gap-3"><BarChart3 className="text-[#50d7e5]" /><div><h2 className="font-bold text-white">Novo Mod</h2><p className="text-xs text-[#777780]">Cadastre uma linha para monitoramento.</p></div></div><input className="input-dark mb-3" value={name} onChange={event => setName(event.target.value)} placeholder="Ex.: Free Fire VIP" /><select className="input-dark" value={status} onChange={event => setStatus(event.target.value as typeof status)}><option value="online">Online (Verde)</option><option value="offline">Offline (Vermelho)</option><option value="maintenance">Manutenção (Amarelo)</option></select><button className="btn-red mt-4 w-full" disabled={!name || create.isPending} onClick={() => create.mutate({ name, status })}>Cadastrar Mod</button></div><div className="surface overflow-hidden rounded-2xl"><div className="border-b border-white/[.06] p-5"><p className="font-bold text-white">Gerenciar status</p></div>{query.data?.length ? <div className="divide-y divide-white/[.06]">{query.data.map(mod => <div key={mod.id} className="flex flex-wrap items-center justify-between gap-3 p-5"><div className="flex items-center gap-3"><span className={`h-3 w-3 rounded-full ${mod.status === "online" ? "bg-[#43c47a] shadow-[0_0_12px_#43c47a]" : mod.status === "offline" ? "bg-[#ff4353]" : "bg-[#f6c55b]"}`} /><p className="font-bold text-white">{mod.name}</p></div><div className="flex items-center gap-2"><select className="input-dark !w-auto py-2 text-xs" value={mod.status} onChange={event => update.mutate({ id: mod.id, status: event.target.value as typeof status })}><option value="online">Online</option><option value="offline">Offline</option><option value="maintenance">Manutenção</option></select><button className="btn-ghost px-2 text-[#ff4353]" onClick={() => remove.mutate({ id: mod.id })}>×</button></div></div>)}</div> : <div className="p-10 text-center text-sm text-[#777780]">Nenhum mod cadastrado.</div>}</div></div></div>;
}

function AdminAnnouncements() {
  const query = trpc.admin.announcements.useQuery(); const [title, setTitle] = useState(""); const [message, setMessage] = useState(""); const create = trpc.admin.createAnnouncement.useMutation({ onSuccess: () => { toast.success("Aviso publicado."); setTitle(""); setMessage(""); query.refetch(); }, onError: error => toast.error(error.message) });
  return <div className="animate-rise"><PageHeading eyebrow="Área de administração" title="Postar Avisos" description="Publique comunicados para deixar registrado o que os clientes precisam saber." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="surface rounded-2xl p-6"><input className="input-dark mb-3" value={title} onChange={event => setTitle(event.target.value)} placeholder="Título do aviso" /><textarea className="input-dark min-h-32 resize-y" value={message} onChange={event => setMessage(event.target.value)} placeholder="Escreva o comunicado..." /><button className="btn-red mt-4 w-full" disabled={!title || !message || create.isPending} onClick={() => create.mutate({ title, message })}><Megaphone size={16} /> Publicar aviso</button></div><div className="surface overflow-hidden rounded-2xl"><div className="border-b border-white/[.06] p-5"><p className="font-bold text-white">Avisos publicados</p></div>{query.data?.map(item => <div key={item.id} className="border-b border-white/[.06] p-5"><p className="font-bold text-white">{item.title}</p><p className="mt-2 text-sm leading-6 text-[#85858e]">{item.message}</p></div>)}</div></div></div>;
}

function AdminAudit() {
  const query = trpc.admin.audit.useQuery(); return <div className="animate-rise"><PageHeading eyebrow="Área de administração" title="Registro de Auditoria" description="Histórico das ações administrativas realizadas no sistema." /><div className="surface overflow-hidden rounded-2xl"><div className="border-b border-white/[.06] p-5"><p className="font-bold text-white">Atividades recentes</p></div>{query.data?.length ? <div className="divide-y divide-white/[.06]">{query.data.map(item => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 p-5"><div><p className="font-semibold text-white">{item.action}</p><p className="mt-1 text-xs text-[#85858e]">{item.details}</p></div><time className="text-xs text-[#777780]">{new Date(item.createdAt).toLocaleString()}</time></div>)}</div> : <div className="p-12 text-center text-sm text-[#777780]">Nenhuma ação registrada ainda.</div>}</div></div>;
}

function AdminPlaceholder({ title, description }: { title: string; description: string }) {
  return <div className="animate-rise"><PageHeading eyebrow="Área de administração" title={title} description={description} /><div className="surface max-w-3xl rounded-2xl p-8"><div className="flex items-center gap-4"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#ed1c2f]/10 text-[#ff4353]"><ShieldCheck size={20} /></span><div><h2 className="text-lg font-bold text-white">Módulo administrativo</h2><p className="mt-1 text-sm text-[#85858e]">Esta área está protegida e disponível somente para o administrador.</p></div></div></div></div>;
}

function AdminApp({ user, setActive, active }: { user: any; setActive: (section: Section) => void; active: Section }) { return <>{active === "overview" && <AdminOverview setActive={setActive} />}{active === "generate" && <AdminGenerate />}{active === "products" && <AdminProducts />}{active === "team" && <AdminTeam />}{active === "support" && <AdminTickets />}{active === "settings" && <Settings />}{active === "resellers" && <AdminResellers />}{active === "inventory" && <AdminProducts />}{active === "mods" && <AdminMods />}{active === "announcements" && <AdminAnnouncements />}{active === "downloads" && <AdminGenerate />}{active === "audit" && <AdminAudit />}</>; }

function ClientApp({ active, setActive }: { active: Section; setActive: (section: Section) => void }) { return <>{active === "overview" && <ClientOverview setActive={setActive} />}{active === "generate" && <ClientGenerate />}{active === "keys" && <ClientKeys />}{active === "support" && <ClientSupport />}</>; }

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [active, setActive] = useState<Section>("overview");
  const admin = useMemo(() => Boolean(user?.role === "admin" || user?.email?.toLowerCase() === OWNER_EMAIL || user?.username?.toLowerCase() === "retzada"), [user]);
  if (loading) return <main className="grid min-h-screen place-items-center bg-[#0b0b0e]"><RefreshCw className="animate-spin text-[#ed1c2f]" size={28} /></main>;
  if (!isAuthenticated) return <LoginScreen />;
  return <Shell user={user} admin={admin} active={active} setActive={setActive} onLogout={logout}>{admin ? <AdminApp user={user} active={active} setActive={setActive} /> : <ClientApp active={active} setActive={setActive} />}</Shell>;
}
